-- Internal AI assistant, Increment 1.2 (docs/AI_ASSISTANT_PLAN.md §8): the registry backfill.
--
-- Every table the public read layer queries, described by hand. Hand-written, not inferred: this
-- is the reference example every later auto-profiled entry (Phase 4) is measured against, so it
-- lands source_kind 'hand_written' / status 'approved' rather than the 'auto' default that
-- extraction output gets (owner decision 5).
--
-- Meanings are taken from each table's own migration header, the ingestion pipeline, and the
-- docs/ write-up that reconciled it — not from reading the data. Where two tables use the same
-- word for differently-measured things (accredited in agg_bhw_counts vs agg_bhw_stepzero_counts;
-- the receiving-only denominator in agg_honorarium_inequality vs the all-profiled denominator in
-- agg_honorarium_cumulative) the dictionary says so, because that distinction is exactly what a
-- generic query tool has no other way to learn.
--
-- Idempotent: re-running refreshes descriptions in place, so this file stays the single source
-- for what the registry says. That is why plan U5's four UUC for PHC objects were added here
-- rather than in a follow-on seed: two files both claiming to describe the registry is the drift
-- this one exists to prevent. The rows added there also close a statement that had gone false —
-- fact_uuc_phc_barangay's note said it had no committed migration, written while PR #75 was still
-- unmerged; 20260826121000_fact_uuc_phc_barangay.sql has been committed since.
--
-- ref_uuc_phc_provincial is a *view*, not a table. It is registered anyway: queryDataset reads it
-- through PostgREST exactly as it reads a table, and refuses any relation with no approved
-- dictionary, so leaving it out would not make it unreachable — it would make it unusable while
-- still being the canonical form of the provincial benchmark.
insert into dataset_registry (
  table_name, title, summary, grain, dataset_slug, exposure, row_estimate,
  source_kind, status, notes_md, doc_path
) values
  ('dim_geo',
   'Geography dimension',
   'Every Philippine geography the dashboard knows, from the national row down to the barangay, on one fixed PSGC vintage. Carries both the containment edge (parent_code) and denormalized ancestor codes.',
   'One geography.',
   null, 'public', 43746, 'hand_written', 'approved',
   'parent_code is a self-referencing containment tree over 43,746 rows. Nothing in the codebase walks it today - getGeoAncestors reads the denormalized region/province/citymun columns instead - so a subtree question needs traverseGraph (Increment 1.6), not this table alone.',
   'docs/BOUNDARY_RECONCILIATION.md'),
  ('dim_dataset',
   'Dataset dimension',
   'One row per source dataset loaded into the warehouse, with its publisher, licence, reference date and the geographic level it joins at. Every fact_ and agg_ row points here.',
   'One source dataset.',
   null, 'public', 9, 'hand_written', 'approved',
   'status active marks the single per-person BHW dataset and is reserved; every other loaded source is published or draft. Never treat a draft dataset as a published figure.',
   'docs/DATASET_SCOPING.md'),
  ('dim_psgc_crosswalk',
   'PSGC vintage crosswalk',
   'Typed, time-bounded identity edges mapping a source-vintage PSGC code onto the current dim_geo code, so external loads on other vintages join without silent loss.',
   'One old_code to new_code mapping at one geographic level.',
   'psa-psgc-crosswalk', 'public', 1787, 'hand_written', 'approved',
   'Read as a graph this is already an edge table: typed relation, validity on both endpoints. map_psgc_to_dim_geo() resolves a single hop only - it cannot follow a chain across two successive vintage changes.',
   'docs/PSGC_CROSSWALK.md'),
  ('agg_geo_summary',
   'Per-geography summary card',
   'The denormalized headline row every place page reads: name, ancestors, profiled headcount, accreditation and honorarium shares, and the full-text search vector.',
   'One geography per dataset.',
   'bhw-2025', 'public', 41052, 'hand_written', 'approved',
   'parent_chain is a fixed three-level flatten built by explicit self-joins in ingestion/build_aggregates.sql, not a traversal - it stops at region/province/citymun and cannot answer an arbitrary-depth ancestry question.',
   null),
  ('agg_bhw_counts',
   'BHW counts and accreditation by geography',
   'Profiled BHW headcount, accreditation share with its Wilson interval, average years active, and the share receiving any honorarium, for every geography.',
   'One geography per dataset.',
   'bhw-2025', 'public', 41052, 'hand_written', 'approved',
   'These are the individually-profiled BHWs of the 2025 snapshot, a subset of the DOH StepZero universe in agg_bhw_stepzero_counts. Never present the two headcounts as the same number.',
   null),
  ('agg_bhw_stepzero_counts',
   'StepZero quick-count by geography',
   'The DOH StepZero barangay headcount baseline: registered, registered-and-accredited and non-registered BHWs, plus the population and household context reported alongside them.',
   'One geography per dataset.',
   'bhw-stepzero-2026', 'public', 43746, 'hand_written', 'approved',
   'Accredited here is a self-reported barangay tally, not the per-person verified accreditation flag in agg_bhw_counts. n_total_bhw is the full BHW universe (Total BHWs); agg_bhw_counts.n_total is the profiled subset (Validated profiles).',
   null),
  ('agg_bhw_profiling_status',
   'BHW Connect profiling status (2026)',
   'How far the 2026 individual-profiling encoding has progressed per geography, through the pipeline Encode to Validate to Certify, against the full 2026 BHW universe.',
   'One geography per dataset.',
   'bhw-profiling-status-2026', 'public', 1788, 'hand_written', 'approved',
   'Two bucket families sit in one row. The universe buckets (n_registered + n_accredited + n_unregistered) sum to n_total_bhw, the denominator. The pipeline buckets are the current status of each encoded record and are mutually exclusive; the four reported stages are derived in lib/db/profiling-status.ts, not stored.',
   'docs/profiling-status-feature.md'),
  ('agg_demographics',
   'BHW demographics by geography',
   'Counts and shares of profiled BHWs by sex, age band, civil status, blood type, education and IP status, with small-cell suppression applied.',
   'One geography x dimension x category per dataset.',
   'bhw-2025', 'public', 530465, 'hand_written', 'approved',
   'Where is_suppressed is true, n and pct are withheld because the cell holds fewer than 5 people. Never state or estimate a suppressed figure; cite the rollup geography instead.',
   null),
  ('agg_training',
   'Training coverage by topic',
   'Share of profiled BHWs trained on each of 44 health topics, with a Wilson interval and the median training year.',
   'One geography x training topic per dataset.',
   'bhw-2025', 'public', 78144, 'hand_written', 'approved',
   'National through city/municipality only - barangay is not stored (a deliberate disk-budget cut), so a barangay question falls back to its city/municipality.',
   null),
  ('agg_certification',
   'Certification coverage',
   'Counts and shares of profiled BHWs holding each certification type.',
   'One geography x certification type per dataset.',
   'bhw-2025', 'public', 123156, 'hand_written', 'approved',
   null,
   null),
  ('agg_honorarium',
   'Honorarium receipt by paying level',
   'Who pays BHW honoraria and how much: recipients, share receiving, and the normalized monthly amount distribution, split by the administrative level that pays.',
   'One geography x paying level per dataset.',
   'bhw-2025', 'public', 93561, 'hand_written', 'approved',
   'One BHW can receive from several levels, so rows do not sum to a headcount. Amounts are normalized to a monthly equivalent from the reported frequency. Where is_suppressed is true the distribution is withheld (fewer than 5 recipients).',
   'docs/HONORARIUM_ANALYSIS_SCOPE.md'),
  ('agg_honorarium_cumulative',
   'Honorarium sufficiency bands',
   'Each BHW total monthly honorarium summed across every paying level, banded into 8 buckets and counted per geography, against a denominator of all profiled BHWs.',
   'One geography x band per dataset.',
   'bhw-2025', 'public', 14208, 'hand_written', 'approved',
   'The denominator is ALL profiled BHWs, so non-recipients land in band 0 (None). This is what makes pct_below_sufficiency a statement about the whole profiled population - unlike agg_honorarium_inequality, whose denominator is recipients only. Sufficiency threshold is PHP 2,040 per month (PHP 68 per day).',
   'docs/HONORARIUM_ANALYSIS_SCOPE.md'),
  ('agg_honorarium_inequality',
   'Honorarium inequality among recipients',
   'Gini coefficient and p90:p10 ratio of total monthly honorarium among BHWs who receive any, per geography.',
   'One geography per dataset.',
   'bhw-2025', 'public', 1770, 'hand_written', 'approved',
   'Denominator is receiving BHWs only - not comparable with agg_honorarium_cumulative, which counts all profiled BHWs. Suppressed below 5 recipients, since an inequality statistic on 1-4 amounts can reveal an individual pay figure. National through city/municipality only.',
   null),
  ('agg_workload',
   'Assigned-household workload distribution',
   'Distribution of assigned households per BHW (p10 to p90 and mean) per geography, plus the share of all households covered by the busiest tenth of BHWs.',
   'One geography per dataset.',
   'bhw-2025', 'public', 1776, 'hand_written', 'approved',
   'n_bhw counts only BHWs reporting a household count above zero; zero and null are excluded as not a real caseload. Distribution columns are suppressed below 5 such BHWs. National through city/municipality only.',
   null),
  ('agg_cohorts',
   'Registration and accreditation cohorts',
   'How many of todays profiled BHWs were registered, accredited, or first became active in each year.',
   'One geography x milestone kind x year per dataset.',
   'bhw-2025', 'public', 103689, 'hand_written', 'approved',
   'Not a time series of the workforce: everyone counted is a current BHW in the 2025 snapshot, so these are milestone years of todays roster, never headcounts as of a past year. Only non-zero cells are stored. National through city/municipality only.',
   null),
  ('agg_by_income_class',
   'Indicators by LGU income class',
   'National indicator summaries grouped by the income class of the city or municipality each BHW barangay belongs to.',
   'One income class (1 to 6), national scope only.',
   'bhw-2025', 'public', 6, 'hand_written', 'approved',
   'Six rows, national only - there is no per-geography breakdown here. Income class comes from dim_geo.income_class.',
   'docs/INCOME_RECLASS.md'),
  ('agg_peer_ranks',
   'Peer ranks and outlier flags',
   'Each geography positioned among its same-parent siblings for six base indicators, with percentile, sibling median, MAD and an outlier flag.',
   'One geography x indicator per dataset.',
   'bhw-2025', 'public', 10668, 'hand_written', 'approved',
   'Sibling edges: regions are ranked among all regions, everything else within its own parent. Region, province and city/municipality only - barangay is not ranked. Joined to a dim_geo subtree walk, this is what answers which places sit below their peers.',
   null),
  ('agg_data_completeness',
   'Field-level missingness',
   'How much of each source field is missing, per geography - the data-quality view behind /data-quality.',
   'One geography x source field per dataset.',
   'bhw-2025', 'public', 14208, 'hand_written', 'approved',
   'Missingness is a property of the source dataset, not a finding about BHWs. National through city/municipality only.',
   null),
  ('agg_population',
   'Census population',
   'PSA census population per geography and census year, name-matched to dim_geo and rolled up from city/municipality leaves.',
   'One geography x census year per source dataset.',
   'psa-popcen-2024', 'public', 3517, 'hand_written', 'approved',
   'Long format across two sources: census_year 2024 comes from dataset psa-popcen-2024, 2020 from psa-cph-2020 - always filter by census_year or dataset_id, never mix them. No barangay population in either release. Reconciliation residuals are enumerated in ingestion/_qa_report_population.json.',
   'docs/POPULATION_RECONCILIATION.md'),
  ('agg_poverty',
   'Small-area poverty estimates',
   'PSA Small Area Estimates of poverty incidence with the coefficient of variation, standard error and 90 percent interval, exactly as published.',
   'One city or municipality x SAE year.',
   'psa-sae-poverty-2023', 'public', 4821, 'hand_written', 'approved',
   'City and municipality grain ONLY. Poverty incidence is a rate and is deliberately not rolled up to province, region or national - there is no published population weighting to do it with. Coverage is 1,607 of 1,651 city/municipalities; residuals (the noHUC scope, BARMM special geographic areas, Kalayaan) are enumerated in the QA report.',
   'docs/POVERTY_SAE.md'),
  ('dim_lgu_income_reclass',
   'DOF LGU income reclassification (2024)',
   'DOF DO 074-2024 (RA 11964) income reclassification, one row per Annex A LGU matched onto dim_geo, with the match method that produced the link.',
   'One reclassified LGU.',
   'dof-blgf-income-2024', 'public', 1724, 'hand_written', 'approved',
   'match_method records how the source row was linked to dim_geo (fuzzy name match, manual override, or province-level). A fuzzy match with a low match_score is a weaker assertion than an override - say so rather than presenting every link as equally certain.',
   'docs/INCOME_RECLASS.md'),
  ('fact_uuc_phc_barangay',
   'Unserved and underserved communities for PHC (2025)',
   'The barangays on the 2025 Unserved and Underserved Communities for Primary Health Care list, with the source name fields they were matched from. Presence in this table means listed.',
   'One listed barangay.',
   'uuc-phc-2025', 'public', 5991, 'hand_written', 'approved',
   'Presence is the fact - there is no listed flag column, so absence means not on the list, not missing data. Built by supabase/migrations/20260826121000_fact_uuc_phc_barangay.sql and loaded by ingestion/ingest_uuc_phc.py. The 9,395 barangays the source workbook assessed and did NOT list were deliberately not loaded, so this table answers "is it on the 2025 list" and cannot answer "was it assessed". Any share of barangays takes its denominator from dim_geo, never from the workbook.',
   'docs/UUC_PHC_2025_PLAN.md'),
  ('agg_uuc_phc_counts',
   'UUC for PHC listed-barangay counts by geography',
   'How many barangays in an area are on the 2025 Unserved and Underserved Communities for Primary Health Care list, against how many barangays the area contains in total.',
   'One geography per dataset.',
   'uuc-phc-2025', 'public', 1788, 'hand_written', 'approved',
   'n_barangays is the dim_geo universe, not the source workbook assessed set - "3 of the 42 barangays in this town" is the statement this table exists to support, and 42 comes from dim_geo. The share is n_listed / n_barangays and is derived in the read layer, never stored, so there is one definition of it. Rows exist for every geography including those with none listed: a 0 is a finding, not missing data. National / region / province / citymun only - barangay rows would restate the fact table as n_listed in {0,1}.',
   'docs/UUC_PHC_2025_PLAN.md'),
  ('fact_uuc_phc_indicators',
   'UUC for PHC 2025 indicator values',
   'The measurements each listed barangay was assessed on: the qualifying factors of DOH AO No. 2020-0023 section VI.A, the 12 cleaned health indicators, and the provincial benchmarks criterion (d) compares each barangay against.',
   'One listed barangay.',
   'uuc-phc-2025', 'public', 5991, 'hand_written', 'approved',
   'CAPPED VALUES. 1,584 values across 1,397 barangays were recorded outside any possible range (Water as high as 9,594 percent, FIC 18,088) and were bounded during cleaning - coverage percentages at 100, rates at 1,000. capped_indicators names, per barangay, which of its values were bounded; 886 Water and 456 FIC values now read as exactly 100 and are indistinguishable from genuine full coverage without it. Never state a value from this table without checking capped_indicators for that barangay, and never average or rank a capped indicator: the marker travels with a single value and cannot survive a mean, which is why this dataset publishes no indicator aggregates at all. Covers the 5,991 listed barangays only - there is no row for an unlisted barangay. The source column Health Indicators (a 0-7 count) is not loaded: it is not recomputable from these columns, so it cannot be checked.',
   'docs/UUC_PHC_2025_CLEANING_REPORT.md'),
  ('ref_uuc_phc_provincial',
   'UUC for PHC provincial benchmarks',
   'One row per province: the benchmark values criterion (d) of DOH AO No. 2020-0023 tests a barangay against, with how many of that province listed barangays actually carry a reference.',
   'One province.',
   'uuc-phc-2025', 'public', 87, 'hand_written', 'approved',
   'A view over fact_uuc_phc_indicators, not a stored table - it runs with security_invoker, so the fact table own public-read policy decides access rather than the view owner. 87 provinces, not the source 88: the source files Zamboanga City under two province names and dim_geo files both under 09317. Read n_with_reference against n_listed_barangays before quoting a benchmark - reference values are all-or-nothing per barangay, and in province 09317 only 1 of 8 listed barangays carries one, so a single value would otherwise stand for the whole province. Five provinces / 238 barangays carry no usable reference at all and cannot support criterion (d); FIC benchmarks are uncapped while barangay FIC values are capped at 100, so 113 barangays in 2 provinces read as worse than their province by construction. To compare one barangay to its province, read that barangay own *_prov_ref columns, which are NULL exactly where the source supplied none.',
   'docs/UUC_PHC_2025_CLEANING_REPORT.md')
on conflict (table_name) do update set
  title = excluded.title,
  summary = excluded.summary,
  grain = excluded.grain,
  dataset_slug = excluded.dataset_slug,
  exposure = excluded.exposure,
  row_estimate = excluded.row_estimate,
  source_kind = excluded.source_kind,
  status = excluded.status,
  notes_md = excluded.notes_md,
  doc_path = excluded.doc_path,
  updated_at = now();

-- The per-column dictionary. allowed_values arrives pipe-separated because several category
-- labels contain commas (PHP 1-4,000) and would otherwise split wrong.
insert into dataset_column (
  registry_id, column_name, ordinal, data_type, allowed_values,
  meaning, unit, role, is_join_key, joins_to, is_queryable, status
)
select
  r.registry_id, c.column_name, c.ordinal, c.data_type,
  case when c.allowed_values is null then null else string_to_array(c.allowed_values, '|') end,
  c.meaning, c.unit, c.role, c.is_join_key, c.joins_to, c.is_queryable, 'approved'
